// Test meshes generated by code, and ways of breaking them.
#pragma once
#include <cstdint>
#include <vector>

#include "gsd/mesh.h"

namespace gsd {

// Sphere by subdivision of an icosahedron.
Mesh icosphere(int subdivisions = 2, double radius = 1.0);
Mesh cube(double size = 1.0);
// Box between two corners, with the triangulation of cube.
Mesh box(const Vec3& lo, const Vec3& hi);
// Puts several meshes together in a single one, without joining them.
Mesh merge_meshes(const std::vector<Mesh>& meshes);
// Removes the faces whose barycenter lies closer than radius to center.
Mesh punch_hole(const Mesh& mesh, const Vec3& center, double radius);
// Makes n_holes holes at random places until roughly the requested fraction of the area has been
// removed. The faces are deleted but the vertices remain, loose inside the holes. With the same
// seed the holes are those of the reference values of the tests.
Mesh random_holes(const Mesh& mesh, double target_fraction, int n_holes = 3, std::uint64_t seed = 0);

}  // namespace gsd
